text(await tools.exec_command({cmd:"cat > App/Tests/DocumentEndScrollTests.swift <<'EOF'
import AppKit
import XCTest
@testable import pType

@MainActor
final class DocumentEndScrollTests: XCTestCase {
    func testCommandDownReachesAndKeepsDocumentEndVisible() throws {
        try withEditor(sectionCount: 500) { document, editor in
            editor.moveToBeginningOfDocument(nil)
            editor.moveToEndOfDocument(nil)
            drain()
            XCTAssertEqual(editor.selectedRange(), NSRange(location: (editor.string as NSString).length, length: 0))
            try assertEndVisible(editor)
            editor.moveToBeginningOfDocument(nil)
            drain()
            XCTAssertEqual(editor.selectedRange(), NSRange(location: 0, length: 0))
            XCTAssertLessThanOrEqual(editor.visibleRect.minY, editor.textContainerOrigin.y)
        }
    }

    func testCommandDownInSinglePassDocument() throws {
        try withEditor(sectionCount: 50) { _, editor in
            editor.moveToEndOfDocument(nil)
            drain()
            try assertEndVisible(editor)
        }
    }

    func testScrollKnobReachesEndAndStaysThereWithoutMovingCaret() throws {
        try withEditor(sectionCount: 500) { _, editor in
            editor.moveToBeginningOfDocument(nil)
            let scroll = try XCTUnwrap(editor.enclosingScrollView)
            let scroller = KnobScroller(frame: .zero)
            scroll.verticalScroller = scroller
            scroller.doubleValue = 1
            XCTAssertTrue(scroller.sendAction(scroller.action, to: scroller.target))
            drain()
            try assertEndVisible(editor)
            XCTAssertEqual(editor.selectedRange(), NSRange(location: 0, length: 0))
            let bottom = scroll.contentView.bounds.maxY
            XCTAssertEqual(bottom, try XCTUnwrap(scroll.documentView).bounds.maxY, accuracy: 1)
        }
    }

    private func withEditor(sectionCount: Int, _ body: (PTypeDocument, NSTextView) throws -> Void) throws {
        let source = String(repeating: "# Performance section\n\nParagraph with **bold**, [link](https://example.com), and `code`.\n\n- [ ] task\n- item\n\n", count: sectionCount) + "UNIQUE-DOCUMENT-END"
        let document = PTypeDocument()
        try document.read(from: Data(source.utf8), ofType: "net.daringfireball.markdown")
        document.makeWindowControllers()
        defer { document.close() }
        let window = try XCTUnwrap(document.windowControllers.first?.window)
        window.setFrame(NSRect(x: 100, y: 100, width: 800, height: 684), display: true)
        window.orderBack(nil)
        drain()
        let editor = try XCTUnwrap(document.undoPublicationTextView)
        window.makeFirstResponder(editor)
        try body(document, editor)
        XCTAssertEqual(document.session.source, source)
    }

    private func assertEndVisible(_ editor: NSTextView, file: StaticString = #filePath, line: UInt = #line) throws {
        let layout = try XCTUnwrap(editor.textLayoutManager)
        var endRect: CGRect?
        layout.enumerateTextSegments(in: NSTextRange(location: layout.documentRange.endLocation), type: .standard, options: []) { _, rect, _, _ in
            var local = rect.offsetBy(dx: editor.textContainerOrigin.x, dy: editor.textContainerOrigin.y)
            local.size.width = max(1, local.width)
            endRect = local
            return false
        }
        let rect = try XCTUnwrap(endRect, file: file, line: line)
        XCTAssertTrue(editor.visibleRect.contains(rect), "End caret \(rect) outside viewport \(editor.visibleRect)", file: file, line: line)
    }

    private func drain() {
        for _ in 0..<100 { RunLoop.main.run(until: Date().addingTimeInterval(0.01)) }
    }
}

@MainActor
private final class KnobScroller: NSScroller {
    override var hitPart: NSScroller.Part { .knob }
}
